{
  "name": "opencode-session-git-badge",
  "version": "0.1.1",
  "description": "Shows a dot on OpenCode Desktop session tabs whose repository has uncommitted changes.",
  "type": "module",
  "license": "MIT",
  "author": "wy17300",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/wyy1300149192/opencode-session-git-badge.git"
  },
  "homepage": "https://github.com/wyy1300149192/opencode-session-git-badge#readme",
  "bugs": {
    "url": "https://github.com/wyy1300149192/opencode-session-git-badge/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "git",
    "desktop"
  ],
  "exports": {
    ".": "./index.ts",
    "./gui-experimental": "./gui-experimental.cjs"
  },
  "files": [
    "index.ts",
    "gui-experimental.cjs",
    "README.md",
    "LICENSE"
  ],
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org",
    "access": "public"
  }
}

import { Plugin } from "@opencode/plugin"

// The GUI part lives in gui-experimental.cjs. This server part only gives the
// package its id, so the desktop app loads the GUI entry instead of treating the
// GUI bundle as a server plugin. It also anchors the file watcher.
export default Plugin.define({
  id: "opencode-session-git-badge",
  setup() {},
})
